function chatUI(){if(!window.CLOK)return;chatLeave();CHAT.alive=true;G=null;
 $("main").innerHTML=`<p class="eb">Illuminati Secret Society</p><div class="wm" style="font-size:30px">LIVE CHAT</div><div class="card"><div class="eb" style="text-align:left;margin:0;display:flex;justify-content:space-between"><span id="lcSt">Connecting…</span><span>clears in <span id="lcCt">10:00</span></span></div><div id="lcMsgs" aria-live="polite"></div><div style="display:flex;gap:8px"><input id="lcI" maxlength="280" placeholder="Message the members" aria-label="Message" autocomplete="off"><button class="pri" id="lcS" type="button" style="width:auto">Send</button></div></div><div class="dock"><button data-act="chatMenu">Back</button></div>`;
 $("#lcS").onclick=chatSend;$("#lcI").addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();chatSend()}});
 chatJoin();chatClock();CHAT.tick=setInterval(chatClock,1000)}

/* ===== 3D intro ===== */
function intro(){const el=$("#intro");menu();if(!el||!window.INTRO3D){el&&el.remove();return}
 let done=0;const go=()=>{if(done)return;done=1;try{INTRO3D.stop()}catch(e){}el.classList.add("out");setTimeout(()=>el.remove(),520)};
 $("#enter").onclick=go;
 let tm=0;const auto=()=>{if(!tm)tm=setTimeout(go,4000)};
 INTRO3D.start(()=>{$("#ildg").textContent="Drag to turn";auto()},()=>{$("#ildg").textContent="";auto()});
 setTimeout(auto,8000);}

intro();

/* ===== fullscreen + landscape ===== */
(function(){
 if(document.documentElement.hasAttribute("data-tg")||document.documentElement.hasAttribute("data-embed"))return;
 const de=document.documentElement;
 const isFS=()=>document.fullscreenElement||document.webkitFullscreenElement;
 function lock(){}
 function goFull(){
  const f=de.requestFullscreen||de.webkitRequestFullscreen;
  if(f&&!isFS()){try{Promise.resolve(f.call(de,{navigationUI:"hide"})).then(lock).catch(()=>{})}catch(e){}}
  else lock();
 }
 function exitFull(){const x=document.exitFullscreen||document.webkitExitFullscreen;if(x)try{x.call(document)}catch(e){}}
  /* first tap enters fullscreen (browsers require a gesture) */
 addEventListener("pointerdown",function once(){goFull();removeEventListener("pointerdown",once,true)},true);
 document.addEventListener("fullscreenchange",()=>{if(isFS())lock()});
 document.addEventListener("webkitfullscreenchange",()=>{if(isFS())lock()});
 lock();
 /* installable as a fullscreen app */
 try{
  const m={name:"Conclave · Illuminati",short_name:"Conclave",start_url:location.href,display:"fullscreen",background_color:"#000000",theme_color:"#000000"};
  const l=document.createElement("link");l.rel="manifest";l.href=URL.createObjectURL(new Blob([JSON.stringify(m)],{type:"application/manifest+json"}));document.head.appendChild(l);
 }catch(e){}
})();

/* ===== inactivity watchdog: 30s with no input while the game waits on you ===== */
(function(){
 let last=Date.now(),wkey="",wstart=Date.now(),busy=0;
 const pill=document.createElement("div");pill.id="afk";pill.style.cssText="position:fixed;left:50%;bottom:max(12px,env(safe-area-inset-bottom));transform:translateX(-50%);z-index:40;padding:8px 14px;border-radius:999px;background:#000;border:1px solid rgba(255,255,255,.3);color:#f0f1f4;font:500 12px var(--sans);letter-spacing:.08em;display:none;white-space:nowrap";document.body.appendChild(pill);
 const act=()=>{last=Date.now();if(typeof G!=="undefined"&&G&&G.away){G.away=0;say("You returned to the table.");render()}};
 ["pointerdown","keydown","touchstart"].forEach(e=>addEventListener(e,act,true));
 const waiting=()=>G&&!G.away&&G.P&&(G.ph=="roll"||G.ph=="buy"||G.ph=="vote"||G.ph=="pick"||(G.ph=="bid"&&G.auc&&G.auc.waiting));
 setInterval(()=>{
  if(!G||!G.P){pill.style.display="none";return}
  const h=$("#hdr");if(h&&G.ph!="over"){const t=hdrT();if(h.textContent!==t)h.textContent=t}
  if(!waiting()){pill.style.display="none";wkey="";return}
  const k=G.ph+"|"+G.cur+"|"+G.r+"|"+(G.auc?G.auc.bid:"");
  if(k!==wkey){wkey=k;wstart=Date.now()}
  const left=Math.ceil((AFK_MS-(Date.now()-Math.max(last,wstart)))/1000);
  if(left<=10&&left>0){pill.textContent="Your move · "+left+"s until your holdings go to bidding";pill.style.display="block"}else pill.style.display="none";
  if(left<=0&&!busy){busy=1;pill.style.display="none";afk().finally(()=>busy=0)}
 },1000);
 async function afk(){
  const p=G.P[0],ph=G.ph;G.away=1;say("You went inactive. The Order acts in your name.");
  if(ph=="roll"){awayTurn(p)}
  else if(ph=="buy"){G.ph="wait";render();await sellAll(p);if(G.away)buy(0);else{G.ph="buy";render()}}
  else if(ph=="vote"){G.ph="wait";render();await sellAll(p);if(G.away)cast(0);else{G.ph="vote";render()}}
  else if(ph=="pick"){const mine=G.own.map((x,k)=>x==0?k:-1).filter(k=>k>=0);pickProp(mine.length?mine[0]:-1)}
  else if(ph=="bid"){bidAns(0)}
  render();
 }
})();

/* Delegated click handler: replaces the old inline onclick attributes so the page needs no inline-script allowance. */
document.addEventListener("click",function(e){const b=e.target&&e.target.closest?e.target.closest("[data-act]"):null;if(!b||b.disabled)return;const v=+b.dataset.v;
 switch(b.dataset.act){
  case"batchUI":batchUI();break;
  case"sel":G.sel=v;render();break;
  case"roll":roll(G.P[0]);break;
  case"buy":buy(v);break;
  case"cast":cast(v);break;
  case"pick":pickProp(v);break;
  case"bid":bidAns(v);break;
  case"menu":menu();break;
  case"leaveMenu":batchLeave();menu();break;
  case"leaveBatch":batchLeave();batchUI("S");break;
  case"chatMenu":chatLeave();menu();break;
 }});
